                  sumbool::left => {
                    sel(k, v89, lo, v70, s, ())
                  },
                  sumbool::right => {
                    v89
                  },
                }
              } else {
                if ltb(k, v91) {
                  v89
                } else {
                  let tmp_6 = ltb(lo, v91);
                  match bdec(tmp_6) {
                    sumbool::left => {
